/* Daily actuals and remaining lots are observations; future risk is explicitly a baseline estimate. */
const dailyState={filter:'all',query:''};
function expiringLots(i){return i.lots.filter(l=>l.qty>0&&l.expiry>=state.date&&l.expiry<=day(state.date,3));}
function dailyMatches(i){return i.ingredient_name.includes(dailyState.query)&&(dailyState.filter==='all'||dailyState.filter==='received'&&i.actual.received_qty>0||dailyState.filter==='waste'&&i.actual.waste_qty>0||dailyState.filter==='expiring'&&expiringLots(i).length>0||dailyState.filter==='risk'&&i.waste>.01);}
function renderDailyInventory(){
    const root=$('#dailyInventory');
    const received=items.filter(i=>i.actual.received_qty>0).length;
    const remainingValue=items.reduce((sum,i)=>sum+i.actual.closing_value,0);
    const wasteCost=items.reduce((sum,i)=>sum+i.actual.waste_records.reduce((a,w)=>a+w.cost,0),0);
    const near=items.filter(i=>expiringLots(i).length>0).length;
    root.innerHTML=`<div class="daily-banner"><div><span class="badge">${state.date>DailyLedger.SEED?(activeSnapshot?.some(i=>i.scenario)?'미래 시나리오':'점장 입력'):'제공 기록'}</span><b>${state.date.replaceAll('-','.')} ${activeSnapshot?.some(i=>i.scenario)?'시나리오':'마감 재고'}를 불러왔어요.</b><p>${state.date>DailyLedger.SEED?'점장이 확인해 저장한 재고입니다. 입고 묶음별 잔량은 운영 가정에 따라 추정하며 다음 날 시작 재고로 이어집니다.':'당일 입고·소진·폐기를 반영한 잔량입니다. 9월 30일 마감 잔량은 10월 1일 시작 재고로 이어집니다.'}</p></div><span class="daily-verified">${state.date>DailyLedger.SEED?'✓ 점장 입력 · 브라우저 저장':'✓ 재고 수지·입고·묶음별 잔량 일치'}</span></div><section class="metrics daily-metrics">${[
        ['당일 실제 입고',n(received),'품목',state.date>DailyLedger.SEED?'점장 확인 입고':'입고 내역과 일별 재고 대조','↓'],
        ['남은 재고 평가금액',n(remainingValue),'원',state.date>DailyLedger.SEED?'9월 말 가상 단가로 평가':'마감 재고 · 제공 가상 평가금액','▥'],
        [state.date>DailyLedger.SEED?'입력 폐기 평가금액':'당일 실제 폐기비용',n(wasteCost),'원',`${items.filter(i=>i.actual.waste_qty>0).length}개 품목 · 폐기 사유 확인 가능`,'◷'],
        ['3일 내 사용기한 도래',n(near),'품목','기한 임박 ≠ 폐기 확정','!']
    ].map(([title,v,unit,foot,icon])=>`<article class="metric"><div class="metric-top">${title}<span class="metric-icon">${icon}</span></div><div class="metric-value">${v}<small>${unit}</small></div><div class="metric-foot">${foot}</div></article>`).join('')}</section><section class="panel"><div class="inventory-heading"><div><div class="eyebrow">DAILY INVENTORY CLOSE</div><h2>당일 입고와 남은 재고</h2><p>${state.date>DailyLedger.SEED?'점장 입력 기록 · 사용·실사 차이는 추정 감소량으로 표시':'수량 흐름은 실제 기록'} · 실제 재고와 사용기한 확인</p></div><button class="button secondary" id="dailyExport">↓ 마감 내역 다운로드</button></div><div class="daily-toolbar"><div class="filters">${[['all','전체'],['received','당일 입고'],['waste','당일 폐기'],['expiring','기한 임박']].map(([key,label])=>`<button class="filter ${key===dailyState.filter?'active':''}" data-daily-filter="${key}">${label}</button>`).join('')}</div><label class="search"><span>⌕</span><input id="dailySearch" aria-label="일일 재고 식자재 검색" placeholder="식자재 검색" value="${escapeHTML(dailyState.query)}"></label></div><div class="table-wrap"><table><thead><tr><th>식자재</th><th>당일 실제 입고</th><th>${state.date>DailyLedger.SEED?'추정 감소량':'당일 소진'}</th><th>당일 실제 폐기</th><th>남은 재고</th><th>가까운 사용기한</th><th></th></tr></thead><tbody id="dailyBody"></tbody></table></div><div id="dailyEmpty" hidden class="empty">조건에 맞는 식자재가 없습니다.</div><div class="table-footer"><span id="dailyCount"></span><span>품목 선택 시 입고 내역·재고 수지·사용기한 확인</span></div></section><section class="daily-next"><div><h3>재고 확인을 마쳤다면 발주 신청으로 이동하세요.</h3><p>입고가 확인되지 않은 예정 물량은 현재 재고에 더하지 않습니다. 기준일을 지난 예정 건은 별도 입고 확인이 필요합니다.</p></div><button class="button primary" id="dailyGoForecast">발주 신청으로 →</button></section>`;
    $$('[data-daily-filter]').forEach(b=>b.onclick=()=>{dailyState.filter=b.dataset.dailyFilter;$$('[data-daily-filter]').forEach(x=>x.classList.toggle('active',x===b));renderDailyRows()});
    $('#dailySearch').oninput=e=>{dailyState.query=e.target.value;renderDailyRows()};
    $('#dailyGoForecast').onclick=()=>{state.nav='overview';state.filter='all';renderTable();applyNav();window.scrollTo({top:0,behavior:'smooth'})};
    $('#dailyExport').onclick=exportDaily;renderDailyRows();
}
function renderDailyRows(){const rows=[...items].filter(dailyMatches).sort((a,b)=>(expiringLots(b).length>0)-(expiringLots(a).length>0)||a.ingredient_id.localeCompare(b.ingredient_id));$('#dailyBody').innerHTML=rows.map(i=>`<tr tabindex="0" data-daily-item="${i.ingredient_id}" aria-label="${escapeHTML(i.ingredient_name)} 일일 재고 상세"><td><div class="item-name"><span class="ingredient-icon">${icons(i)}</span><div><b>${escapeHTML(i.ingredient_name)}</b><small>${i.ingredient_id} · ${i.storage}</small></div></div></td><td>${i.actual.received_qty>0?qty(i.actual.received_qty,i):'<span class="muted">없음</span>'}</td><td>${qty(i.actual.consumed_qty,i)}</td><td>${i.actual.waste_qty>0?`<span class="expiry-warn">${qty(i.actual.waste_qty,i)}</span>`:'<span class="muted">없음</span>'}</td><td><b class="daily-stock">${qty(i.stock,i)}</b></td><td>${i.nearest?`${i.nearest} <small class="history-sub">${days(state.date,i.nearest)}일 후 · ${i.lots.filter(l=>l.qty>0).length}개 입고 묶음</small>${expiringLots(i).length?'<span class="badge waste">임박</span>':''}`:'<span class="muted">잔량 없음</span>'}</td><td><button class="row-arrow" aria-label="${i.ingredient_id} 일일 상세 보기">↗</button></td></tr>`).join('');$('#dailyEmpty').hidden=rows.length>0;$('#dailyCount').textContent=`식자재 ${items.length}개 중 ${rows.length}개 표시 · 단위가 다른 품목 수량은 합산하지 않습니다.`;$$('[data-daily-item]').forEach(row=>{row.onclick=()=>openDailyItem(row.dataset.dailyItem);row.onkeydown=e=>{if(e.key==='Enter')openDailyItem(row.dataset.dailyItem)}});}
function openDailyItem(id){const i=items.find(i=>i.ingredient_id===id),a=i.actual;showDrawer(`<div class="drawer-header"><div><div class="eyebrow">DAILY CLOSE RECORD</div><h2>${escapeHTML(i.ingredient_name)}</h2><p>${state.date} 마감 기준 · ${DATA.stores.find(s=>s.store_id===state.store).store_name}</p></div><button class="icon-button close-drawer" aria-label="닫기">×</button></div><span class="badge">${i.scenario?'미래 시나리오 기록':i.source==='manager'?'점장 입력 기록':'제공 실제 기록'}</span><div class="drawer-summary"><div class="drawer-stat"><small>당일 실제 입고</small><strong>${qty(a.received_qty,i)}</strong></div><div class="drawer-stat"><small>마감 잔량</small><strong>${qty(i.stock,i)}</strong></div></div><h3>당일 실제 입고 내역</h3><table><thead><tr><th>발주서</th><th>받은 포장 수량</th><th>사용단위 환산</th></tr></thead><tbody>${a.receipts.map(r=>`<tr><td>${r.po}</td><td>${n(r.packs,3)} ${escapeHTML(r.unit)}</td><td>${qty(r.qty,i)}</td></tr>`).join('')||'<tr><td colspan="3">당일 실제 입고 없음</td></tr>'}</tbody></table><h3>재고 수지 · 실제 기록</h3>${[
['기초재고',a.opening_qty],['+ 당일 입고',a.received_qty],['± 실사 조정',a.adjust_qty],['+ 기존 이동입고',a.transfer_in_qty],['− 기존 이동출고',a.transfer_out_qty],[i.source==='manager'?'− 추정 감소량 (판매·실사 차이 포함)':'− 판매 소진',a.consumed_qty],['− 실제 폐기',a.waste_qty],['= 마감 잔량',i.stock]
].map(([label,v])=>`<div class="calc-line">${label}<b>${qty(v,i)}</b></div>`).join('')}${lotTrackingHTML(i)}<h3>당일 폐기 사유 · 실제 기록</h3>${a.waste_records.map(w=>`<div class="calc-line">${escapeHTML(w.reason)}<b>${qty(w.qty,i)} · ${money(w.cost)}</b></div>`).join('')||'<p>당일 폐기 기록 없음</p>'}<h3>입고 예정 · 현재 잔량과 별개</h3>${i.pending.map(p=>`<div class="calc-line">${p.date} 예정<b>${qty(p.qty,i)}</b></div>`).join('')||'<p>기준일까지 발주한 미입고 물량 없음</p>'}<button class="button primary" id="dailyDetailForecast">이 품목의 발주 신청으로 →</button>`);$('#dailyDetailForecast').onclick=()=>{closeDrawer();state.nav='overview';state.selected=id;state.filter='all';renderTable();applyNav();$('#chartSelect').value=id;renderChart();$('#analysisRow').scrollIntoView({behavior:'smooth',block:'start'})};}
function exportDaily(){const rows=[['기준일','매장','식자재','사용단위','기초재고','실제입고','실사조정','소진','실제폐기','마감재고','가까운사용기한'],...items.filter(dailyMatches).map(i=>[state.date,state.store,i.ingredient_name,i.use_unit,i.actual.opening_qty,i.actual.received_qty,i.actual.adjust_qty,i.actual.consumed_qty,i.actual.waste_qty,i.stock,i.nearest||''])],csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=`재고마감_${state.store}_${state.date}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('조회 중인 마감 재고 내역을 다운로드했습니다.');}
